// H/L 扇出走 In1；CLK/Q 走 B，避免同层互穿
const fanTop = (net, src, jPad, layer, runY, colX) => {
  if (!net || !src || !jPad) return;
  const esc = { x: src.x + (src.x < 2300 ? 40 : -40), y: src.y };
  add(net, src, esc, 12, 'F.Cu');
  addVia(net, esc);
  L(net, [esc, { x: esc.x, y: runY }, { x: colX, y: runY }, { x: colX, y: jPad.y }], 12, layer);
  addVia(net, { x: colX, y: jPad.y });
  add(net, { x: colX, y: jPad.y }, jPad, 12, 'F.Cu');
};
const fanSide = (net, src, jPad, layer, colX) => {
  if (!net || !src || !jPad) return;
  const esc = { x: src.x + (src.x < 2300 ? 40 : -40), y: src.y };
  add(net, src, esc, 12, 'F.Cu');
  addVia(net, esc);
  L(net, [esc, { x: colX, y: esc.y }, { x: colX, y: jPad.y }], 12, layer);
  addVia(net, { x: colX, y: jPad.y });
  add(net, { x: colX, y: jPad.y }, jPad, 12, 'F.Cu');
};
fanTop(logicH, pw('U6', 1), jH, 'In1.Cu', 90, 2280);
fanTop(logicL, pw('U6', 2), jL, 'In1.Cu', 130, 2320);
fanTop(clk, pw('U7', 13), jClk, 'B.Cu', 170, 2360);
fanSide(la[0], pw('U7', 3), jQ0, 'B.Cu', 2400);
fanSide(la[1], pw('U7', 2), jQ1, 'B.Cu', 2440);
fanSide(la[2], pw('U7', 4), jQ2, 'B.Cu', 2480);
